const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/budget_views/%7Bbudget_view_id%7D/budget_details',
  qs: {project_id: 'SOME_INTEGER_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {
    filters: {
      biller: [{value: [56], type: 'SubJob', name: 'North Building'}],
      cost_code: [1],
      root_cost_code: [1],
      cost_type: [1],
      vendor: [1],
      detail_type: ['original_budget_amount']
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/budget_views/%7Bbudget_view_id%7D/budget_details?project_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"filters\":{\"biller\":[{\"value\":[56],\"type\":\"SubJob\",\"name\":\"North Building\"}],\"cost_code\":[1],\"root_cost_code\":[1],\"cost_type\":[1],\"vendor\":[1],\"detail_type\":[\"original_budget_amount\"]}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
